    "id": "backend-skill-scanner",
    "name": "Skill Scanner",
    "category": "Backend Systems",
    "subcategory": "Agent Skill Authoring",
    "description": "Scan agent skills for security issues. Use when asked to \"scan a skill\",",
    "triggers": [],
